export function soundDisplayName(sound: Pick<SoundItem, "id" | "name" | "isBuiltin">): string {
  if (!sound.isBuiltin || !Object.hasOwn(BUILTIN_SOUND_NAMES, sound.id)) return sound.name;
  const definition = BUILTIN_SOUND_NAMES[sound.id as keyof typeof BUILTIN_SOUND_NAMES];
  return sound.name === definition.original ? editorMessage(definition.key) : sound.name;
}
